SINA_SMART["infect-tiac"] = {"lecture":"infect-tiac","title":"Collective foodborne toxi-infections (TIAC)","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"infect-tiac:e0","text":"TIAC: ≥ 2 grouped cases, similar (digestive) symptoms, same food; notifiable.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"infect-tiac:e1","text":"Mostly bacterial.","topic":"The big picture","sec":0,"importance":"core","highYield":"untested"},{"id":"infect-tiac:e2","text":"S. aureus: 2-4 h, vomiting, no fever (dairy, dishes made the day before).","topic":"Clues to the germ","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-tiac:e3","text":"C. perfringens: isolated afebrile diarrhoea (collective catering, poor refrigeration).","topic":"Clues to the germ","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-tiac:e4","text":"Salmonella: 12-24 h, febrile diarrhoea (eggs, poultry).","topic":"Clues to the germ","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-tiac:e5","text":"Campylobacter, Shigella, Yersinia: 48-72 h, febrile.","topic":"Clues to the germ","sec":1,"importance":"core","highYield":"untested"},{"id":"infect-tiac:e6","text":"Rehydration first; avoid antidiarrhoeal transit slowers in invasive diarrhoea.","topic":"Management","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-tiac:e7","text":"Antibiotics only if > 48-72 h, salmonella, dysentery, cholera or risk factors.","topic":"Management","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-tiac:e8","text":"Collective: report, investigate, remove food, test kitchen staff.","topic":"Management","sec":2,"importance":"core","highYield":"untested"},{"id":"infect-tiac:e9","text":"Prevention: hands, no cooked-raw contact, < 2 h out of fridge, fridge < 4.5 °C.","topic":"Prevention","sec":3,"importance":"core","highYield":"untested"}],"vmap":{},"mlevel":{"1y1by15":"a","7wp987":"a","ivgqnt":"a","6t6nm":"a","1vnulj3":"a","1rtucdp":"a","19aip30":"a","o7g2j3":"a","v1z4pr":"a","ud0144":"a","119zyta":"a"},"mapCounts":{"verified":0,"auto":11,"ambiguous":0,"missing":0},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"infect-tiac:e0":{"s":0,"u":["TIAC: ≥ 2 grouped cases, similar (digestive) symptoms, same food; notifiable.","A collective foodborne toxi-infection (TIAC) is at least two grouped cases with similar, usually digestive (gastroenteritis) symptoms, linked to the same food .","It is a notifiable disease ."],"dp":[]},"infect-tiac:e1":{"s":0,"u":["Mostly bacterial.","The causes are essentially bacterial ; the incubation period and the presence of fever point to the germ."],"dp":[]},"infect-tiac:e2":{"s":1,"u":["S. aureus: 2-4 h, vomiting, no fever (dairy, dishes made the day before).","Short incubation (under 12 h), no fever : preformed toxins: Staphylococcus aureus ( 2-4 h ; vomiting , abdominal pain, diarrhoea without fever; milk and dairy, dishes prepared the day before) and Bacillus cereus .","Clostridium perfringens : isolated diarrhoea without fever , from dishes prepared the day before, inadequate refrigeration, collective catering ."],"dp":[{"h":"Why a short incubation and no fever mean a toxin","t":"When bacteria such as Staphylococcus aureus grow in food left at room temperature, they release heat-stable toxins into it. Eating the food delivers the toxin directly, so vomiting starts within a few hours, and since no infection is established there is no fever. Invasive bacteria like Salmonella must first multiply and invade the gut wall, which takes longer and causes fever. Source: the lecture's pathogen table."},{"h":"Why dishes prepared the day before are risky","t":"Cooking kills most bacteria but not the spores of Clostridium perfringens or Bacillus cereus. If a large dish cools slowly and sits out, the spores germinate and multiply, producing toxin, and reheating may not destroy it. That is why collective catering and leftovers appear again and again in TIAC investigations. Source: the lecture's pathogen and prevention slides."}]},"infect-tiac:e3":{"s":1,"u":["C. perfringens: isolated afebrile diarrhoea (collective catering, poor refrigeration).","Clostridium perfringens : isolated diarrhoea without fever , from dishes prepared the day before, inadequate refrigeration, collective catering ."],"dp":[]},"infect-tiac:e4":{"s":1,"u":["Salmonella: 12-24 h, febrile diarrhoea (eggs, poultry).","Longer incubation (over 12 h), with fever : Salmonella ( 12-24 h ; acute febrile diarrhoea; undercooked or raw meat, poultry, eggs , seafood), Campylobacter , Shigella , Yersinia ( 48-72 h ; acute febrile diarrhoea; undercooked or raw food)."],"dp":[]},"infect-tiac:e5":{"s":1,"u":["Campylobacter, Shigella, Yersinia: 48-72 h, febrile.","Longer incubation (over 12 h), with fever : Salmonella ( 12-24 h ; acute febrile diarrhoea; undercooked or raw meat, poultry, eggs , seafood), Campylobacter , Shigella , Yersinia ( 48-72 h ; acute febrile diarrhoea; undercooked or raw food)."],"dp":[]},"infect-tiac:e6":{"s":2,"u":["Rehydration first; avoid antidiarrhoeal transit slowers in invasive diarrhoea.","Rehydration is the priority ; antipyretics for fever; continue or resume feeding early, avoiding stimulating foods (raw vegetables, fruit, dairy); antisecretory agents; digestive dressings of unproven value; avoid transit slowers (opioids, anticholinergics), which are contraindicated in invasive diarrhoea."],"dp":[]},"infect-tiac:e7":{"s":2,"u":["Antibiotics only if > 48-72 h, salmonella, dysentery, cholera or risk factors.","Antibiotics are not systematic : only for symptoms beyond 48-72 h, suspected salmonellosis, bacterial dysentery, cholera, or risk factors (infants, elderly, immunocompromised, valve disease); options by germ: fluoroquinolones, azithromycin, cotrimoxazole .","Admit for major digestive intolerance or weight loss with risk factors."],"dp":[]},"infect-tiac:e8":{"s":2,"u":["Collective: report, investigate, remove food, test kitchen staff.","Collective : mandatory reporting ; epidemiological investigation to identify and remove the responsible food and the faulty procedures; search for carriers among kitchen staff (stool culture, nose and throat swabs)."],"dp":[]},"infect-tiac:e9":{"s":3,"u":["Prevention: hands, no cooked-raw contact, < 2 h out of fridge, fridge < 4.5 °C.","Refrigeration : refrigerate or freeze perishables; do not leave prepared dishes or leftovers more than 2 hours unrefrigerated; fridge below 4.5 °C ."],"dp":[]}},"meta":{"1y1by15":{"a":"recall","vg":"infect-tiac:e0/recall/1"},"7wp987":{"a":"recall","vg":"infect-tiac:e0/recall/2"},"ivgqnt":{"a":"recall","vg":"infect-tiac:e2/recall/1"},"6t6nm":{"a":"recall","vg":"infect-tiac:e3/recall/1"},"1vnulj3":{"a":"recall","vg":"infect-tiac:e4/recall/1"},"1rtucdp":{"a":"recall","vg":"infect-tiac:e5/recall/1"},"19aip30":{"a":"recall","vg":"infect-tiac:e6/recall/1"},"o7g2j3":{"a":"relationship","vg":"infect-tiac:e6/relationship/1"},"v1z4pr":{"a":"recall","vg":"infect-tiac:e7/recall/1"},"ud0144":{"a":"recall","vg":"infect-tiac:e8/recall/1"},"119zyta":{"a":"recall","vg":"infect-tiac:e9/recall/1"}},"explRev":"f5c5adb5d967"};
